        'emailIdentityArn': emailIdentityArn,
        'configurationSet': configurationSet,
        'roleArn': roleArn,
        'externalId': externalId,
        'accessKey': accessKey,
        'secretKey': secretKey,
        'acceptKeyRisk': acceptKeyRisk,
        'deliveryEventsEnabled': deliveryEventsEnabled,
        'snsTopicArn': snsTopicArn
    });

